use crate::cmd::init::ShellIntegration;

pub fn emit_init_script(integration: ShellIntegration) {
    print!("{}", HEADER);
    match integration {
        ShellIntegration::False => {}
        ShellIntegration::True => print!("{}", SAFE_WRAPPER),
        ShellIntegration::Force => print!("{}", FORCE_WRAPPER),
    }
    print!("{}", COMPLETION);
}

const HEADER: &str = r#"
# git-mate shell integration — generated by `git-mate init zsh`
# Add this to your ~/.zshrc:
#   eval "$(command git-mate init zsh)"
"#;

const FORCE_WRAPPER: &str = r#"
# Auto-cd support
function git() {
    local _proto _exit
    _proto=$(mktemp) || return 1
    GIT_MATE_PROTO="$_proto" command git "$@"
    _exit=$?
    eval "$(command git-mate _protocol --zsh "$_proto")"
    rm -f "$_proto"
    return $_exit
}
"#;

const SAFE_WRAPPER: &str = r#"
# Auto-cd support
if [[ "$(type -w git 2>/dev/null)" == "git: function" ]]; then
    print "git-mate: warning: 'git' is already a shell function; skipping git() wrapper. Set mate.shellIntegration=force to override." >&2
else
    function git() {
        local _proto _exit
        _proto=$(mktemp) || return 1
        GIT_MATE_PROTO="$_proto" command git "$@"
        _exit=$?
        eval "$(command git-mate _protocol --zsh "$_proto")"
        rm -f "$_proto"
        return $_exit
    }
fi
"#;

const COMPLETION: &str = r#"
# Shell completions for `git-mate` and `git mate`
#
# Values (e.g. branches) are listed before flags. clap's stock zsh completer
# puts everything in one sorted group, which floats `--flags` to the top.
_git_mate_complete() {
    local -a completions dirs values flags
    completions=("${(@f)$( \
        _CLAP_IFS=$'\n' \
        _CLAP_COMPLETE_INDEX=$(( CURRENT - 1 )) \
        COMPLETE=zsh \
        command git-mate -- "${words[@]}" 2>/dev/null \
    )}")
    [[ -n $completions ]] || return 1

    local completion value
    for completion in $completions; do
        value="${completion%%:*}"
        if [[ $value == -* ]]; then
            flags+=("$completion")
        elif [[ $value == */ ]]; then
            dirs+=("${value%/}${completion#$value}")
        else
            values+=("$completion")
        fi
    done

    local ret=1
    (( $#values )) && _describe -t values 'values' values -V git-mate-values && ret=0
    (( $#dirs )) && _describe -t directories 'directories' dirs -S '/' -r '/' -V git-mate-dirs && ret=0
    (( $#flags )) && _describe -t flags 'flags' flags -V git-mate-flags && ret=0
    return ret
}
compdef _git_mate_complete git-mate
_git-mate() {
    words[1]="git-mate"
    _git_mate_complete
}
# Register 'mate' as a known git subcommand (for `git ma<TAB>`)
() {
    local -a _cmds
    zstyle -a ':completion:*:*:git:*' user-commands _cmds
    (( ${_cmds[(I)mate:*]} )) || _cmds+=('mate:manage git worktrees')
    zstyle ':completion:*:*:git:*' user-commands $_cmds
}
"#;
